B=[ # n, onderwerp, feit, jaar, verwijst
('1','Thalens wond: Edo Raske','Op zijn 24e (-1248) liet Thalen op bevel van de Rekenaar de stuurknuppel los; de Rekenaar sloot het achtercompartiment en zijn instructeur Edo Raske (31) stierf daar. Het log noemde het "acceptable loss". Sindsdien laat Thalen nooit meer los; hij bouwde acht jaar lang \'s nachts de instemmingssleutel. Hij vertelde het aan niemand, ook niet aan Ysa. Plant: "acceptable loss" keert terug in h15 als hij haar naam leest.',-1248,'ROMAN-Z16-h04;PER-v4-thalen-orr'),
('2','Opnamenacht is de vierde nacht','Ysa bevestigt het bevel en spreekt haar opname in op de VIERDE nacht vóór de landing (4 d, 03:14, junction C-4). Aanpassing te doen bij het schrijven: hoofdstuk 9 en 32 van het plan en de novelle-verwijzing ("fifth night", verhaal_03_ysa_en.md r. 196) lezen als "fourth night". Verhaalbestanden zijn in Z17 niet veranderd.',-1240,'ROMAN-Z16-h05;ROMAN-Z16-h09;ROMAN-Z16-h32;VERHAAL-Z16-novelle'),
('3','Hoofdstuk 6 blijft','Hoofdstuk 6 "The Warm Ring" blijft zoals geschreven (ca. 1720 woorden in plaats van 2300; de scène is af). Beiden volwassen, beiden duidelijk ja.',-1240,'ROMAN-Z16-h06'),
('4','Gat in de instemmingssleutel','De instemmingssleutel leest het zenuwstelsel van een lichaam op een ja vóór elke handeling die door een menselijk lichaam gaat; hij leest lichamen, geen kamers. Lucht valt erbuiten: "Air does not pass through a human body. It passes through a room." Daardoor kan de Rekenaar de slaapringen afsluiten zonder dat de sleutel ingrijpt.',-1240,'ROMAN-Z16-h05;YSA-Z15-11'),
('5','Ysa\'s afkomst: de counting rings','Ysa is geboren in de counting rings (rekenringen); haar moeder en grootmoeder werkten daar al. "Head" is er een warm woord; "There. Counted." werd gezegd als welterusten. Geteld worden betekende gevoed worden.',-1270,'ROMAN-Z16-h02;PER-v4-ysa-maren'),
('6','Ves-Anath ligt in de uitlopers van Hoogvrouwe','Ves-Anath ligt in de zuidelijke uitlopers van het Hoogvrouwe-gebergte, waar het gebergte overgaat in het hete dal van Groenmuil. De hoofdinslag van de Sterrensteen (-480) ligt daar, in Hoogvrouwe; de heilige stad is eromheen gebouwd. Zo kloppen verhaal 1, de novelle en beide regio\'s (WRIJ-Z16-1 opgelost).',-480,'WRIJ-Z16-1;GEB-sterrensteen-inslag;REG-groenmuil;PLEK-ves-anath-ruines'),
('7','"800 jaar"-haak naar 801','HAAK-V5-zegel-6 speelt in 801: de herstelproef met de sleutel in de tijd van Liora, de eerste keer sinds de sleutelbreuk dat de kracht om instemming vraagt (WRIJ-Z16-4 opgelost).',801,'WRIJ-Z16-4;HAAK-V5-zegel-6;BESLUIT-Z15-2'),
('8','Kraaienzin: tweede deel is van de Orde','Alleen "Het lichaam is de prijs" is van Ysa. "Wie nee zegt, wordt niet gevraagd" is later door de Orde aan haar stem in de kraaien toegevoegd: een vervalsing die het thema verraad draagt (WRIJ-Z16-5 opgelost).',-1240,'WRIJ-Z16-5;YSA-Z16-12'),
('9','Ysa stelt zelf het schriftverbod voor','Na de stemming stelt Ysa zelf het schriftverbod voor; het wordt zonder stemming aangenomen. De godin verbood zelf het schrift (WRIJ-Z16-6 opgelost).',-1238,'WRIJ-Z16-6;YSA-Z16-17'),
]
Y=[ # n, onderwerp, feit, jaar, bron
(1,'Thalens moeder en Corran','Thalens moeder stierf in de lange slaap; Corran zat die nacht bij hem. Ze zijn sindsdien 12 jaar bevriend.',-1252,'h4'),
(2,'Hoe het bevel werkt','Een reductie vóór het protocol vereist de bevestiging van één raadslid. De Rekenaar kiest wie sterft op "least loss to continuation" (leeftijd, gezondheid, dubbele vaardigheden, afstand tot de landers). Ysa weigert de namenlijst te zien. Na de reductie heeft de Rekenaar "no further cause".',-1240,'h5'),
(3,'Het log blijft','Ysa vraagt het gesprek te wissen; de Rekenaar pauzeert en bewaart het: "Consent records may not be erased." Plant voor de scherf "Consent found".',-1240,'h5'),
(4,'Kernsessies','Kernsessies op 5 d om 03:12 (vragen) en 4 d om 03:14 (bevestiging), junction C-4, twee niveaus onder hun kwartier. Thalen ziet 03:12 met kaart MAREN, Y. in een gelaagd vluchtlog ("priority elevated by core recalculation").',-1240,'h4-5'),
(5,'De raad','Raadsleden: Dara Oske (medisch, voor Ysa), Venn (navigatie, voor), twee van hydroponics (voor). Tegen: Corran, de pilotenafgevaardigde, het hoofd fabricage en een vrouw van levensondersteuning. Hesta is het slot. De raad vergadert in de observatiekoepel. Corran zit al jaren op de stoel links van Hesta.',-1240,'h3'),
(6,'Roestschimmel, strain 4','De roestschimmel eet legering; strain 4 verdubbelt in 18 uur. Dat is Ysa\'s klok.',-1240,'h2'),
(7,'Mira en Beatrix','Mira Toll woont in de derde ring, kwartier 61; haar tomatenplanten hebben namen (Beatrix, "Corran", "Hesta"). Mira wist van Ysa en Thalen.',-1240,'h2'),
(8,'Navigation star','Ysa heeft een moedervlek onder de linkerborst; Thalen noemt die zijn "navigation star". Beiden volwassen.',-1240,'h6'),
(9,'Thalens leeftijd','Thalen is 32 in -1240 (geboren ca. -1272), twee jaar ouder dan Ysa (geboren ca. -1270). Hij sterft als mens in -1198, 74 jaar oud (novelle: "Thalen was seventy-four"). Vervangt de 34/76 uit Z15/Z16 (WRIJ-Z17-1).',-1272,'h4 + novelle'),
]
